(()=>{
const $=s=>document.querySelector(s);
const isContact=!!$('#enquiry-form'),isAccount=!!$('#account-auth'),isAdmin=!!$('#admin-auth');
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});let body;try{body=await r.json();}catch{throw new Error('The service is unavailable. Please try again shortly.');}if(!r.ok){const err=new Error(body.error||body.message||'Your request could not be completed. Please try again.');err.status=r.status;throw err;}return body;}
const identity=api('/api/me').catch(()=>({authenticated:false,user:null,unavailable:true}));
function text(el,value){el.textContent=value??'';return el;}
function node(tag,className,value){const el=document.createElement(tag);if(className)el.className=className;if(value!==undefined)el.textContent=value;return el;}
function date(value){try{return new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));}catch{return value;}}
function requestCard(request,admin=false){const card=node('article','request-card'),top=node('div','request-top'),heading=node('div');heading.append(node('p','eyebrow',request.type==='b2b'?'BUSINESS ENQUIRY':'GENERAL ENQUIRY'),node('h3','',request.interest||'Coffee enquiry'));const status=node('span','request-status '+request.status,request.status);top.append(heading,status);card.append(top);if(admin)card.append(node('p','request-person',`${request.name}${request.company?' · '+request.company:''}`),node('p','request-contact',`${request.email}${request.phone?' · '+request.phone:''}`));if(request.volume)card.append(node('p','request-volume','Requirement: '+request.volume));card.append(node('p','request-message',request.message),node('p','request-meta',date(request.createdAt)+' · Reference '+request.id.slice(0,8)));
if(admin){const label=node('label','status-editor','Update status'),select=document.createElement('select');select.setAttribute('aria-label','Status for '+request.name);for(const val of ['new','contacted','quoted','closed']){const opt=node('option','',val[0].toUpperCase()+val.slice(1));opt.value=val;select.append(opt);}select.value=request.status;const result=node('span','status-result');select.addEventListener('change',async()=>{const previous=request.status;select.disabled=true;result.textContent='Saving…';try{await api('/api/admin/enquiries/'+encodeURIComponent(request.id),{method:'PATCH',body:JSON.stringify({status:select.value})});request.status=select.value;status.className='request-status '+request.status;status.textContent=request.status;result.textContent='Saved';}catch(e){select.value=previous;result.textContent=e.message;}finally{select.disabled=false;}});label.append(select,result);card.append(label);}return card;}
if(isContact){const form=$('#enquiry-form'),params=new URLSearchParams(location.search);let user=null;
function setType(type){form.elements.type.value=type;document.querySelectorAll('[data-enquiry-type]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.enquiryType===type)));const b2b=type==='b2b';form.elements.company.required=b2b;$('#company-label').firstChild.textContent=b2b?'Business / company name':'Business / company name (optional)';$('#volume-label').hidden=!b2b;$('#enquiry-heading').textContent=b2b?'Let’s talk coffee.':'What’s on your mind?';$('#enquiry-description').textContent=b2b?'Tell us about your business and the coffee you’re looking for.':'Questions about our coffee, your preferences, or a partnership? Start here.';}
setType(params.get('type')==='contact'?'contact':'b2b');document.querySelectorAll('[data-enquiry-type]').forEach(b=>b.addEventListener('click',()=>setType(b.dataset.enquiryType)));
try{const saved=JSON.parse(sessionStorage.getItem('pulpoffe-enquiry-draft')||'null');if(saved){for(const key of ['name','email','company','phone','interest','volume','message'])if(typeof saved[key]==='string'&&form.elements[key])form.elements[key].value=saved[key];if(saved.type==='contact')setType('contact');}if(params.get('from')==='basket'){const selection=sessionStorage.getItem('pulpoffe-enquiry-selection');if(selection){form.elements.message.value='I’d like to enquire about these coffees:\n\n'+selection+'\n\nPlease confirm pack sizes, prices and delivery options.';form.elements.interest.value='Multiple collections';}}}catch{}
identity.then(state=>{user=state.user;const note=$('#form-auth-note');note.replaceChildren();if(user){note.append(node('span','','Signed in as '+user.email));if(!form.elements.name.value)form.elements.name.value=user.name||'';if(!form.elements.email.value)form.elements.email.value=user.email;form.querySelector('[type=submit]').innerHTML='Send enquiry <span>↗</span>';}else{note.append(node('span','',state.unavailable?'Sign-in service is temporarily unavailable.':'Sign in securely to send and track your enquiry.'));const a=node('a','underlined','Continue with ChatGPT ↗');a.href='/signin-with-chatgpt?return_to='+encodeURIComponent('/contact.html?type='+form.elements.type.value);a.target='_top';a.addEventListener('click',saveDraft);note.append(a);form.querySelector('[type=submit]').innerHTML='Sign in to send <span>↗</span>';}});
function payload(){const data=new FormData(form);return Object.fromEntries([...data.entries()].map(([k,v])=>[k,k==='consent'?true:String(v)]));}
function saveDraft(){try{sessionStorage.setItem('pulpoffe-enquiry-draft',JSON.stringify(payload()));}catch{}}
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;if(!user){saveDraft();location.assign('/signin-with-chatgpt?return_to='+encodeURIComponent('/contact.html?type='+form.elements.type.value));return;}const button=form.querySelector('[type=submit]'),status=$('#enquiry-status');button.disabled=true;status.textContent='Sending your enquiry…';try{const result=await api('/api/enquiries',{method:'POST',body:JSON.stringify(payload())});status.replaceChildren(node('strong','','Your enquiry has been received.'),node('span','',' Reference: '+result.id.slice(0,8)+'. '));const link=node('a','underlined','Track it in My account ↗');link.href='account.html';status.append(link);try{sessionStorage.removeItem('pulpoffe-enquiry-draft');sessionStorage.removeItem('pulpoffe-enquiry-selection');}catch{}form.reset();form.elements.type.value='b2b';setType('b2b');form.elements.name.value=user.name||'';form.elements.email.value=user.email;}catch(err){status.textContent=err.message;if(err.status===401){saveDraft();status.append(node('span','',' Please sign in again.'));}}finally{button.disabled=false;}});
api('/api/contact-settings').then(data=>{if(!data.published)return;const details=$('#contact-details');details.replaceChildren(node('h2','','Let’s keep in touch.'));if(data.email){const a=node('a','',data.email);a.href='mailto:'+data.email;details.append(a);}if(data.phone){const a=node('a','',data.phone);a.href='tel:'+data.phone.replace(/[^+\d]/g,'');details.append(a);}if(data.address)details.append(node('p','',data.address));}).catch(()=>{});
}
if(isAccount){identity.then(async state=>{if(!state.user){if(state.unavailable)$('#account-error').textContent='Account service is temporarily unavailable. Please try again shortly.';return;}$('#account-auth').hidden=true;$('#account-content').hidden=false;text($('#account-name'),state.user.name||'Welcome back.');text($('#account-email'),state.user.email);$('#admin-entry').hidden=state.user.role!=='admin';const host=$('#customer-requests');host.textContent='Loading your enquiries…';try{const data=await api('/api/enquiries');host.replaceChildren();if(!data.enquiries.length){host.append(node('p','empty-state','Your next coffee conversation starts here. You haven’t sent an enquiry yet.'));}else data.enquiries.forEach(r=>host.append(requestCard(r)));}catch(e){host.textContent=e.message;}});}
if(isAdmin){let requests=[];
function render(){const selected=$('#request-filter').value,list=requests.filter(r=>selected==='all'||r.status===selected),host=$('#admin-requests');host.replaceChildren();$('#inbox-count').textContent=list.length+' request'+(list.length===1?'':'s');if(!list.length)host.append(node('p','empty-state','No enquiries in this view.'));else list.forEach(r=>host.append(requestCard(r,true)));}
async function refresh(){const host=$('#admin-requests');host.textContent='Loading enquiries…';try{const data=await api('/api/admin/enquiries');requests=data.enquiries;render();}catch(e){host.textContent=e.message;}}
identity.then(async state=>{if(!state.user){if(state.unavailable)$('#admin-error').textContent='Admin service is temporarily unavailable. Please try again shortly.';return;}if(state.user.role!=='admin'){$('#admin-auth').hidden=true;$('#admin-error').textContent='This account is not authorised to manage Pulpoffe. Your customer account is available in My account.';return;}$('#admin-auth').hidden=true;$('#admin-content').hidden=false;$('#admin-user').textContent='Signed in as '+state.user.email;await refresh();try{const settings=await api('/api/admin/contact-settings');const form=$('#contact-settings-form');for(const name of ['email','phone','address'])form.elements[name].value=settings[name]||'';form.elements.published.checked=!!settings.published;}catch(e){$('#settings-status').textContent=e.message;}});
$('#request-filter').addEventListener('change',render);$('#refresh-inbox').addEventListener('click',refresh);document.querySelectorAll('[data-admin-tab]').forEach(b=>b.addEventListener('click',()=>{const settings=b.dataset.adminTab==='settings';$('#admin-settings').hidden=!settings;$('#admin-inbox').hidden=settings;document.querySelectorAll('[data-admin-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
$('#contact-settings-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('[type=submit]');button.disabled=true;$('#settings-status').textContent='Saving…';try{await api('/api/admin/contact-settings',{method:'PATCH',body:JSON.stringify({email:form.elements.email.value,phone:form.elements.phone.value,address:form.elements.address.value,published:form.elements.published.checked})});$('#settings-status').textContent=form.elements.published.checked?'Saved. These contact details are now published.':'Saved as unpublished contact details.';}catch(err){$('#settings-status').textContent=err.message;}finally{button.disabled=false;}});
}
})();
